def parse(s, idx):
    if s[idx].isdigit():
        num = ""
        while idx < len(s) and s[idx].isdigit():
            num += s[idx]
            idx += 1
        return int(num), idx

    op_end = s.find('(', idx)
    op = s[idx:op_end]
    idx = op_end + 1

    args = []
    while s[idx] != ')':
        val, idx = parse(s, idx)
        args.append(val)
        if s[idx] == ',':
            idx += 1

    idx += 1
    if op == "add":
        return sum(args), idx
    elif op == "sub":
        res = args[0]
        for x in args[1:]:
            res -= x
        return res, idx
    elif op == "mul":
        res = 1
        for x in args:
            res *= x
        return res, idx
    return 0, idx

