def get_grundy(n):
    if n < 3:
        return 0
    if n in memo:
        return memo[n]

    reachable_grundy = set()
    # Splitting n into a and b where a+b=n, a!=b, a,b >= 1
    # This is equivalent to a != n/2.
    for a in range(1, (n + 1) // 2):
        b = n - a
        if a != b:
            reachable_grundy.add(get_grundy(a) ^ get_grundy(b))

    # MEX calculation
    res = 0
    while res in reachable_grundy:
        res += 1
    memo[n] = res
    return res

