def count_distinct_prime_factors(n: int) -> int:
    n = abs(n)
    if n < 2:
        return 0
    count = 0
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count += 1
            while temp % d == 0:
