import re

def tokenize(s):
    return re.findall(r'\d+|\+|\*|\(|\)', s)

def parse(tokens):
    def get_expr(idx):
        stack = []
        while idx < len(tokens):
            t = tokens[idx]
            if t == '(':
                sub, next_idx = get_expr(idx + 1)
                stack.append(sub)
                idx = next_idx
            elif t == ')':
                return build_tree(stack), idx + 1
            else:
                stack.append(t)
                idx += 1
        return build_tree(stack), idx

    def build_tree(stack):
        # Handle multiplication first (higher precedence)
        i = 0
        while i < len(stack):
            if stack[i] == '*':
                left, op, right = stack[i-1], stack[i], stack[i+1]
                stack[i-1:i+2] = [('mul', left, right)]
            else:
                i += 1
        # Handle addition
        i = 0
        while i < len(stack):
            if stack[i] == '+':
                left, op, right = stack[i-1], stack[i], stack[i+1]
                stack[i-1:i+2] = [('add', left, right)]
            else:
                i += 1
        return stack[0]

    def to_str(node):
        if isinstance(node, str):
            return node
        t, l, r = node
        op = '+' if t == 'add' else '*'
        return f"({to_str(l)}{op}{to_str(r)})"

    tree, _ = get_expr(0)
    return to_str(tree)

