# dp[r][c][rem_k] stores the lexicographically smallest path from (r, c) to (n-1, m-1)
# with sum rem_k. Using None to denote unreachable.
memo = {}

def get_path(r, c, rem):
    if r >= n or c >= m or rem < grid[r][c]:
        return None
    if r == n - 1 and c == m - 1:
        return [(r, c)] if rem == grid[r][c] else None

    state = (r, c, rem)
    if state in memo:
        return memo[state]

    res = None
    # Try moving right, then down to ensure lexicographical order preference
    # because the path is a sequence of coordinates.
    for dr, dc in [(0, 1), (1, 0)]:
