def compute(tokens):
    if not isinstance(tokens, list):
        return tokens
    res = compute(tokens[0])
    i = 1
    while i < len(tokens):
        op = tokens[i]
        val = compute(tokens[i + 1])
        if op == '+':
            res += val
        else:
            res -= val
        i += 2
    return res

def parse(tokens):
    stack = [[]]
    for t in tokens:
        if t == '(':
            new_list = []
            stack[-1].append(new_list)
            stack.append(new_list)
        elif t == ')':
            stack.pop()
        else:
            val = int(t) if t.isdigit() else t
            stack[-1].append(val)
    return stack[0]

